similarity = FileAttachment("data/similarity.csv").csv({ typed: true })
albumsRaw = FileAttachment("data/albums.csv").csv({ typed: true })

albums = albumsRaw.filter(d =&gt; {
  const name = `${d.title} (${d.year})`
  return similarity.some(s =&gt; s["Album 1"] === name || s["Album 2"] === name)
})

viewof selectedArtist = Inputs.select([...new Set(albums.map(d =&gt; d.artist))], {
  label: "Select an artist:"
})

filteredAlbums = albums.filter(d =&gt; d.artist === selectedArtist)

viewof selected = Inputs.select(filteredAlbums, {
  label: "Select an album:",
  format: d =&gt; `${d.title} (${d.year})`
})

html`
&lt;div class="album-card" style="max-width: 420px; margin-top: 20px; margin-bottom: 35px; text-align: left;"&gt;
  &lt;div style="font-size: 0.85rem; font-weight: 600; text-transform: uppercase; letter-spacing: 0.05em; color: #6c757d; margin-bottom: 4px;"&gt;
    ${selected?.artist}
  &lt;/div&gt;
  &lt;h3 style="margin-top: 0; margin-bottom: 12px; font-size: 1.3rem;"&gt;
    ${selected?.title} &lt;span style="font-weight: normal; color: #6c757d;"&gt;(${selected?.year})&lt;/span&gt;
  &lt;/h3&gt;
  &lt;img src="data/${selected?.cover_filename}" alt="${selected?.title}" style="width: 100%; border-radius: 8px; box-shadow: 0 4px 10px rgba(0,0,0,0.12);" onerror="this.style.display='none'; this.nextElementSibling.style.display='block';"&gt;
  &lt;p style="display:none; color: #888; font-style: italic; margin-top: 8px;"&gt;Cover image not available.&lt;/p&gt;
&lt;/div&gt;
`

Cover Color Similarity

selectedAlbumName = selected ? `${selected.title} (${selected.year})` : ""

matches = similarity
  .filter(d =&gt; d["Album 1"] === selectedAlbumName || d["Album 2"] === selectedAlbumName)
  .map(d =&gt; {
    const isFirst = d["Album 1"] === selectedAlbumName;
    const albumName = isFirst ? d["Album 2"] : d["Album 1"];
    const artistName = isFirst ? d["Artist 2"] : d["Artist 1"];
    const info = albums.find(a =&gt; `${a.title} (${a.year})` === albumName);
    return {
      album: albumName,
      artist: artistName,
      similarity: d["Similarity"],
      cover: info ? info.cover_filename : null
    };
  })
  .sort((a, b) =&gt; b.similarity - a.similarity)

mostSimilar = matches[0]
mostDifferent = matches[matches.length - 1]

html`
${!mostSimilar ? html`&lt;p style="color: #888; font-style: italic;"&gt;No similarity data available for this album.&lt;/p&gt;` : html`
&lt;div style="display: flex; gap: 24px; flex-wrap: wrap; margin-top: 20px;"&gt;
  &lt;div class="album-card" style="flex: 1; min-width: 240px; max-width: 300px;"&gt;
    &lt;div class="similarity-badge badge-similar"&gt;★ Most Similar • ${mostSimilar.similarity}%&lt;/div&gt;
    &lt;img src="data/${mostSimilar.cover}" alt="${mostSimilar.album}" style="width: 100%; border-radius: 8px; box-shadow: 0 2px 8px rgba(0,0,0,0.1);"&gt;
    &lt;p style="margin-top: 12px; font-weight: 600; margin-bottom: 2px;"&gt;${mostSimilar.album}&lt;/p&gt;
    &lt;p style="color: #6c757d; font-size: 0.9rem; margin-top: 0;"&gt;${mostSimilar.artist}&lt;/p&gt;
  &lt;/div&gt;
  &lt;div class="album-card" style="flex: 1; min-width: 240px; max-width: 300px;"&gt;
    &lt;div class="similarity-badge badge-different"&gt;⚡ Most Different • ${mostDifferent.similarity}%&lt;/div&gt;
    &lt;img src="data/${mostDifferent.cover}" alt="${mostDifferent.album}" style="width: 100%; border-radius: 8px; box-shadow: 0 2px 8px rgba(0,0,0,0.1);"&gt;
    &lt;p style="margin-top: 12px; font-weight: 600; margin-bottom: 2px;"&gt;${mostDifferent.album}&lt;/p&gt;
    &lt;p style="color: #6c757d; font-size: 0.9rem; margin-top: 0;"&gt;${mostDifferent.artist}&lt;/p&gt;
  &lt;/div&gt;
&lt;/div&gt;
`}
`
